package com.sneakerhouse.backend.controller;
import com.sneakerhouse.backend.entity.Product; import com.sneakerhouse.backend.repository.ProductRepository; import com.sneakerhouse.backend.dto.ProductResponse; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*; import org.springframework.transaction.annotation.Transactional;
@RestController @RequestMapping("/api/products") public class ProductController {
 private final ProductRepository repo; public ProductController(ProductRepository r){repo=r;}
 @GetMapping @Transactional(readOnly=true) public Map<String,Object> search(@RequestParam(required=false) String keyword,@RequestParam(required=false) Long categoryId,@RequestParam(required=false) Long brandId,@RequestParam(required=false) BigDecimal minPrice,@RequestParam(required=false) BigDecimal maxPrice,@RequestParam(required=false) String size,@RequestParam(required=false) String color,@RequestParam(defaultValue="newest") String sort,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="12") int sizePerPage){
 if(page<0||sizePerPage<1||sizePerPage>100) throw new IllegalArgumentException("page phải >= 0 và sizePerPage từ 1 đến 100"); if(minPrice!=null&&maxPrice!=null&&minPrice.compareTo(maxPrice)>0) throw new IllegalArgumentException("minPrice không được lớn hơn maxPrice");
 Specification<Product> s=(root,q,cb)->cb.isTrue(root.get("active"));
 if(keyword!=null&&!keyword.isBlank()){String k="%"+keyword.trim().toLowerCase()+"%"; s=s.and((r,q,cb)->cb.or(cb.like(cb.lower(r.get("name")),k),cb.like(cb.lower(r.get("sku")),k),cb.like(cb.lower(r.join("brand",jakarta.persistence.criteria.JoinType.LEFT).get("name")),k)));}
 if(categoryId!=null)s=s.and((r,q,cb)->cb.equal(r.get("category").get("id"),categoryId)); if(brandId!=null)s=s.and((r,q,cb)->cb.equal(r.get("brand").get("id"),brandId));
 if(minPrice!=null)s=s.and((r,q,cb)->cb.greaterThanOrEqualTo(cb.coalesce(r.get("salePrice"),r.get("originalPrice")),minPrice)); if(maxPrice!=null)s=s.and((r,q,cb)->cb.lessThanOrEqualTo(cb.coalesce(r.get("salePrice"),r.get("originalPrice")),maxPrice));
 if(size!=null&&!size.isBlank())s=s.and((r,q,cb)->cb.like(r.get("sizes"),"%"+size.trim()+"%")); if(color!=null&&!color.isBlank())s=s.and((r,q,cb)->cb.like(cb.lower(r.get("colors")),"%"+color.trim().toLowerCase()+"%"));
 Sort order=switch(sort.toLowerCase()){case "price_asc"->Sort.by("salePrice").ascending().and(Sort.by("originalPrice").ascending());case "price_desc"->Sort.by("salePrice").descending().and(Sort.by("originalPrice").descending());case "best_selling"->Sort.by("soldCount").descending();case "newest"->Sort.by("createdAt").descending();default->throw new IllegalArgumentException("sort chỉ nhận newest, price_asc, price_desc, best_selling");};
 Page<Product> result=repo.findAll(s,PageRequest.of(page,sizePerPage,order)); Map<String,Object> out=new LinkedHashMap<>();out.put("content",result.getContent().stream().map(ProductResponse::from).toList());out.put("page",result.getNumber());out.put("size",result.getSize());out.put("totalElements",result.getTotalElements());out.put("totalPages",result.getTotalPages());out.put("last",result.isLast());return out;
 }
}
